from datetime import timedelta
from decimal import ROUND_HALF_UP, Decimal

DUPLICATE_WINDOW = timedelta(days=2)


def _money(amount):
    # Go through str() so that float values such as 54.20 become exact decimals.
    return Decimal(str(amount))


def _parse_month(month):
    year, mon = month.split("-")
    return int(year), int(mon)


def _in_month(txn, year, mon):
    return txn.day.year == year and txn.day.month == mon


def summarize(transactions, month):
    """Return {category: net total} for transactions dated in `month` ("YYYY-MM").

    Totals are rounded to 2 decimals; categories whose net total is exactly 0 are omitted.
    """
    year, mon = _parse_month(month)
    totals = {}
    for txn in transactions:
        if not _in_month(txn, year, mon):
            continue
        totals[txn.category] = totals.get(txn.category, Decimal(0)) + _money(txn.amount)

    result = {}
    for category, total in totals.items():
        if total == 0:
            continue
        result[category] = float(total.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))
    return result


def find_duplicates(transactions):
    """Return (earlier_id, later_id) pairs with the same payee and amount, dated at most 2 days apart.

    Refunds (negative amounts) are never duplicates. The list is sorted by the
    earlier transaction's date, then its id.
    """
    candidates = [t for t in transactions if t.amount >= 0]
    candidates.sort(key=lambda t: (t.day, t.id))

    pairs = []
    for i, first in enumerate(candidates):
        for second in candidates[i + 1:]:
            if second.day - first.day > DUPLICATE_WINDOW:
                break  # sorted by date, so no later transaction can be within the window
            if second.payee == first.payee and _money(second.amount) == _money(first.amount):
                pairs.append((first, second))

    pairs.sort(key=lambda p: (p[0].day, p[0].id, p[1].day, p[1].id))
    return [(a.id, b.id) for a, b in pairs]

